-- S2 Signal — SingleStore schema (database `gtm_dashboard`).
--
-- Ported from the Supabase/Postgres schema of the original Signal dashboard.
-- Postgres -> SingleStore translation rules used throughout:
--   uuid default gen_random_uuid()  -> VARCHAR(36), generated by the app (lib/s2/client.ts)
--   jsonb                           -> JSON
--   timestamptz                     -> DATETIME(6), always written and read as UTC
--   boolean                         -> BOOL
--   text used in a key              -> VARCHAR(n) (keys cannot be TEXT)
--   partial / expression indexes    -> enforced in application code
--   RLS policies                    -> enforced in lib/s2 (per-user tables are
--                                      scoped to the session user automatically)
--
-- Table types, chosen per workload:
--   * High-volume, scan-heavy tables (signals, directory, briefs, GitHub
--     activity, contacts, caches) are sharded COLUMNSTORE tables: the feed and
--     the directory are analytical reads over thousands of rows. Every unique
--     key contains the shard key, as SingleStore requires.
--   * Small, constraint-heavy, transactional tables (users, sequences,
--     prospects, enrollments, OAuth connections) are ROWSTORE REFERENCE tables:
--     replicated to every node, so they join locally with anything and can
--     carry several unique keys (rowstore allows that; columnstore limits it).

-- ---------------------------------------------------------------------------
-- Auth (replaces Supabase Auth / GoTrue)
-- ---------------------------------------------------------------------------
CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_users (
  id            VARCHAR(36)  NOT NULL,
  email         VARCHAR(320) NOT NULL,
  password_hash VARCHAR(200) NOT NULL,          -- scrypt$N$salt$hash
  created_at    DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  UNIQUE KEY (email)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_profiles (
  user_id      VARCHAR(36)  NOT NULL,
  display_name VARCHAR(120) NOT NULL,
  created_at   DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (user_id)
);

-- ---------------------------------------------------------------------------
-- Signal feed, briefs, directory (the core prospecting data)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gtm_signals (
  id            VARCHAR(36)  NOT NULL,
  account       VARCHAR(300) NOT NULL,
  segment       VARCHAR(40)  NOT NULL,
  type          VARCHAR(24)  NOT NULL,
  strength      INT          NOT NULL,
  title         TEXT         NOT NULL,
  description   TEXT         NOT NULL,
  tags          JSON,
  source        VARCHAR(300) NOT NULL DEFAULT '',
  url           TEXT,
  event_date    DATE,
  swe_estimate  INT,
  codebase_hint TEXT,
  region        VARCHAR(8)   NOT NULL DEFAULT 'us',
  created_at    DATETIME(6)  NOT NULL DEFAULT NOW(6),
  last_seen_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (account),
  SORT KEY (last_seen_at),
  UNIQUE KEY (account, type) USING HASH,
  KEY (region) USING HASH
);

CREATE TABLE IF NOT EXISTS gtm_briefs (
  company_key  VARCHAR(300) NOT NULL,
  company      VARCHAR(300) NOT NULL,
  intel        JSON         NOT NULL,
  generated_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);

CREATE TABLE IF NOT EXISTS gtm_directory (
  company_key         VARCHAR(300) NOT NULL,
  company             VARCHAR(300) NOT NULL,
  domain              VARCHAR(300),
  region              VARCHAR(8)   DEFAULT 'us',
  segment             VARCHAR(40),
  swe_estimate        INT,
  short_brief         TEXT,
  employee_band       VARCHAR(40),
  estimated_employees INT,
  website_url         TEXT,
  linkedin_url        TEXT,
  strength            INT          DEFAULT 0,
  source              VARCHAR(40)  DEFAULT 'directory',
  created_at          DATETIME(6)  NOT NULL DEFAULT NOW(6),
  last_seen_at        DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  SORT KEY (strength),
  UNIQUE KEY (company_key) USING HASH
);

-- Legacy single-document state (read by the GitHub prospector for prospected marks).
CREATE TABLE IF NOT EXISTS gtm_state (
  store      VARCHAR(120) NOT NULL,
  value      JSON         NOT NULL,
  updated_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (store),
  UNIQUE KEY (store) USING HASH
);

-- Per-user client state (favorites, prospected marks, reviewed…). Scoped to the
-- session user by lib/s2 (the Supabase version relied on RLS).
CREATE TABLE IF NOT EXISTS gtm_user_state (
  user_id    VARCHAR(36)  NOT NULL,
  store      VARCHAR(120) NOT NULL,
  value      JSON         NOT NULL,
  updated_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (user_id),
  UNIQUE KEY (user_id, store) USING HASH
);

-- ---------------------------------------------------------------------------
-- Shared row-per-entry caches (/api/cache)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gtm_scores (
  company_key VARCHAR(300) NOT NULL,
  score       INT          NOT NULL,
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_company_blurbs (
  company_key VARCHAR(300) NOT NULL,
  blurb       TEXT         NOT NULL,
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_sweep_cursor (
  cursor_key VARCHAR(300) NOT NULL,
  page       INT          NOT NULL DEFAULT 0,
  updated_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (cursor_key),
  UNIQUE KEY (cursor_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_blacklist (
  company_key VARCHAR(300) NOT NULL,
  company     VARCHAR(300) NOT NULL,
  created_by  VARCHAR(36),
  created_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_contact_reviews (
  `key`       VARCHAR(400) NOT NULL,
  verdict     VARCHAR(16)  NOT NULL,     -- qualified | excluded
  user_id     VARCHAR(36),
  reviewed_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (`key`),
  UNIQUE KEY (`key`) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_swe_overrides (
  company_key VARCHAR(300) NOT NULL,
  swe         INT          NOT NULL,
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_brief_swe (
  company_key VARCHAR(300) NOT NULL,
  swe         INT          NOT NULL,
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_spend_overrides (
  company_key VARCHAR(300) NOT NULL,
  spend_mo    INT          NOT NULL,
  updated_at  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (company_key),
  UNIQUE KEY (company_key) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_reveal_cache (
  apollo_id      VARCHAR(64)  NOT NULL,
  name           VARCHAR(300),
  email          VARCHAR(320),
  email_status   VARCHAR(40),
  phone          VARCHAR(64),
  country        VARCHAR(80),
  linkedin_url   TEXT,
  company_domain VARCHAR(300),
  revealed_by    VARCHAR(36),
  updated_at     DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (apollo_id),
  UNIQUE KEY (apollo_id) USING HASH
);
CREATE TABLE IF NOT EXISTS gtm_sync_events (
  id          VARCHAR(36)  NOT NULL,
  kind        VARCHAR(16)  NOT NULL,     -- company | contact
  `key`       VARCHAR(400) NOT NULL,
  company_key VARCHAR(300),
  contact_key VARCHAR(400),
  user_id     VARCHAR(36)  NOT NULL,
  portal_id   VARCHAR(64),
  task_url    TEXT,
  synced_at   DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (id),
  SORT KEY (synced_at),
  UNIQUE KEY (id) USING HASH
);

-- ---------------------------------------------------------------------------
-- Proposals (prospect-facing pages at /p/<token>)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gtm_proposals (
  token        VARCHAR(32)  NOT NULL,
  company      VARCHAR(300) NOT NULL,
  company_key  VARCHAR(300) NOT NULL,
  contact_name VARCHAR(300),
  fields       JSON         NOT NULL,
  created_by   VARCHAR(36),
  created_at   DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at   DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (token),
  UNIQUE KEY (token) USING HASH,
  KEY (company_key) USING HASH
);

-- ---------------------------------------------------------------------------
-- GitHub prospecting
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gtm_monitored_repos (
  repo_key       VARCHAR(300) NOT NULL,
  owner          VARCHAR(200) NOT NULL,
  name           VARCHAR(200) NOT NULL,
  category       VARCHAR(60)  NOT NULL DEFAULT 'database',
  why_matters    TEXT         NOT NULL,
  active         BOOL         NOT NULL DEFAULT TRUE,
  stars          INT,
  poll_cursor    JSON         NOT NULL,
  last_polled_at DATETIME(6),
  added_at       DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (repo_key),
  UNIQUE KEY (repo_key) USING HASH
);

CREATE TABLE IF NOT EXISTS gtm_github_signals (
  id         VARCHAR(36)  NOT NULL,
  login      VARCHAR(200) NOT NULL,
  repo_key   VARCHAR(300) NOT NULL,
  action     VARCHAR(40)  NOT NULL,
  action_at  DATETIME(6)  NOT NULL,
  weight     INT          NOT NULL DEFAULT 0,
  detail     TEXT,
  url        TEXT,
  created_at DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (login),
  SORT KEY (action_at),
  UNIQUE KEY (login, repo_key, action, action_at) USING HASH,
  KEY (repo_key) USING HASH
);

CREATE TABLE IF NOT EXISTS gtm_enriched_contacts (
  login              VARCHAR(200) NOT NULL,
  name               VARCHAR(300),
  avatar_url         TEXT,
  github_url         TEXT,
  location           VARCHAR(300),
  company            VARCHAR(300),
  company_domain     VARCHAR(300),
  resolution_source  VARCHAR(60),
  status             VARCHAR(24)  NOT NULL DEFAULT 'new',
  suppressed_reason  TEXT,
  apollo_person_id   VARCHAR(64),
  email              VARCHAR(320),
  title              VARCHAR(300),
  seniority          VARCHAR(60),
  linkedin_url       TEXT,
  headcount          INT,
  hubspot_contact_id VARCHAR(64),
  hubspot_company_id VARCHAR(64),
  score              INT          NOT NULL DEFAULT 0,
  best_action        VARCHAR(40),
  best_repo          VARCHAR(300),
  signal_summary     JSON,
  opener             TEXT,
  last_signal_at     DATETIME(6),
  created_at         DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at         DATETIME(6)  NOT NULL DEFAULT NOW(6),
  SHARD KEY (login),
  SORT KEY (score),
  UNIQUE KEY (login) USING HASH,
  KEY (status) USING HASH
);

-- ---------------------------------------------------------------------------
-- HubSpot OAuth (tokens encrypted at rest by the app before they land here)
-- ---------------------------------------------------------------------------
CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_hubspot_connections (
  user_id           VARCHAR(36)  NOT NULL,
  portal_id         VARCHAR(64)  NOT NULL,
  hub_domain        VARCHAR(300),
  hs_user_email     VARCHAR(320),
  owner_id          VARCHAR(64),
  access_token_enc  TEXT         NOT NULL,
  refresh_token_enc TEXT         NOT NULL,
  expires_at        DATETIME(6)  NOT NULL,
  scopes            TEXT,
  connected_at      DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at        DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (user_id)
);

-- ---------------------------------------------------------------------------
-- Sequencer
-- ---------------------------------------------------------------------------
CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_prospects (
  id                 VARCHAR(36)  NOT NULL,
  email              VARCHAR(320),
  first_name         VARCHAR(120),
  last_name          VARCHAR(120),
  title              VARCHAR(300),
  company            VARCHAR(300),
  company_key        VARCHAR(300),
  company_domain     VARCHAR(300),
  country            VARCHAR(80),
  timezone           VARCHAR(64),
  linkedin_url       TEXT,
  linkedin_urn       VARCHAR(200),
  apollo_person_id   VARCHAR(64),
  github_login       VARCHAR(200),
  hubspot_contact_id VARCHAR(64),
  classification     VARCHAR(16),
  evidence_depth     VARCHAR(24),
  source_section     VARCHAR(24),
  do_not_contact     BOOL         NOT NULL DEFAULT FALSE,
  dnc_reason         VARCHAR(16),
  dnc_channel        VARCHAR(24),
  dnc_at             DATETIME(6),
  created_by         VARCHAR(36),
  created_at         DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at         DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  UNIQUE KEY (email),
  UNIQUE KEY (apollo_person_id),
  KEY (company_key)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_sequences (
  id                     VARCHAR(36)  NOT NULL,
  name                   VARCHAR(200) NOT NULL,
  owner_user_id          VARCHAR(36)  NOT NULL,
  active                 BOOL         NOT NULL DEFAULT TRUE,
  default_timezone       VARCHAR(64)  NOT NULL DEFAULT 'America/New_York',
  send_window_start_hour INT          NOT NULL DEFAULT 8,
  send_window_end_hour   INT          NOT NULL DEFAULT 17,
  created_at             DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at             DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_sequence_steps (
  id               VARCHAR(36)  NOT NULL,
  sequence_id      VARCHAR(36)  NOT NULL,
  step_order       INT          NOT NULL,
  channel          VARCHAR(24)  NOT NULL,
  delay_hours      INT          NOT NULL DEFAULT 0,
  branch_condition VARCHAR(32),
  subject          TEXT,
  body             TEXT,
  created_at       DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  UNIQUE KEY (sequence_id, step_order)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_enrollments (
  id                  VARCHAR(36) NOT NULL,
  prospect_id         VARCHAR(36) NOT NULL,
  sequence_id         VARCHAR(36) NOT NULL,
  enrolled_by_user_id VARCHAR(36) NOT NULL,
  current_step        INT         NOT NULL DEFAULT 0,
  state               VARCHAR(16) NOT NULL DEFAULT 'active',
  stop_reason         VARCHAR(32),
  next_action_at      DATETIME(6),
  created_at          DATETIME(6) NOT NULL DEFAULT NOW(6),
  updated_at          DATETIME(6) NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  KEY (prospect_id),
  KEY (next_action_at)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_action_log (
  id                          VARCHAR(36)  NOT NULL,
  enrollment_id               VARCHAR(36)  NOT NULL,
  step_id                     VARCHAR(36),
  channel                     VARCHAR(24)  NOT NULL,
  idempotency_key             VARCHAR(200) NOT NULL,
  sent_from_mailbox           VARCHAR(320),
  sent_to_email               VARCHAR(320),
  sent_from_linkedin_account  VARCHAR(200),
  status                      VARCHAR(16)  NOT NULL,
  provider_message_id         VARCHAR(400),
  provider_conversation_id    VARCHAR(400),
  error                       TEXT,
  claimed_at                  DATETIME(6)  NOT NULL DEFAULT NOW(6),
  executed_at                 DATETIME(6),
  PRIMARY KEY (id),
  UNIQUE KEY (idempotency_key),
  KEY (enrollment_id)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_sequence_events (
  id            VARCHAR(36) NOT NULL,
  prospect_id   VARCHAR(36),
  enrollment_id VARCHAR(36),
  type          VARCHAR(24) NOT NULL,
  channel       VARCHAR(24),
  payload       JSON,
  dedupe_key    VARCHAR(300),
  processed_at  DATETIME(6),
  occurred_at   DATETIME(6) NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  UNIQUE KEY (dedupe_key)
);

CREATE ROWSTORE REFERENCE TABLE IF NOT EXISTS gtm_m365_mailboxes (
  id                      VARCHAR(36)  NOT NULL,
  user_id                 VARCHAR(36)  NOT NULL,
  email                   VARCHAR(320) NOT NULL,
  display_name            VARCHAR(200),
  access_token_enc        TEXT         NOT NULL,
  refresh_token_enc       TEXT         NOT NULL,
  expires_at              DATETIME(6)  NOT NULL,
  scopes                  TEXT,
  active                  BOOL         NOT NULL DEFAULT TRUE,
  needs_reconnect         BOOL         NOT NULL DEFAULT FALSE,
  subscription_id         VARCHAR(200),
  subscription_expires_at DATETIME(6),
  connected_at            DATETIME(6)  NOT NULL DEFAULT NOW(6),
  updated_at              DATETIME(6)  NOT NULL DEFAULT NOW(6),
  PRIMARY KEY (id),
  UNIQUE KEY (email)
);
